```json
{
  "status": "designed",
  "request": "List the review-roster people together with their profile-shown workspaces, keeping only entries for roster members who themselves posted about the launch in the audit channel histories (C_LAUNCH1, C_LAUNCH2). Roster candidates: U_ROSTER1, U_ROSTER2, U_ROSTER3, U_ROSTER4.",
  "selection_plan": {
    "root_entity": "WORKSPACE_MEMBERSHIP",
    "route": "WORKSPACE_MEMBERSHIP -> USER -> MESSAGE",
    "focal_condition": "The membership's user is the author (messages.user_id) of a message in the audit channel histories whose message_text contains 'launch'.",
    "auxiliary_conditions": [
      "User is one of the supplied review-roster candidate IDs (U_ROSTER1..U_ROSTER4).",
      "Workspace shown is the single workspace association exposed by users.info for that user."
    ],
    "candidate_scope": "Four roster users, each with one users.info-exposed workspace membership; two audit channels (C_LAUNCH1, C_LAUNCH2) fully readable by the actor and paginated in full."
  },
  "resolution_plan": {
    "mode": "multiple",
    "intended_members": [
      "Membership pair for the roster user who authored a launch-related message in C_LAUNCH1",
      "Membership pair for a second roster user who authored a launch-related message in C_LAUNCH2"
    ],
    "justification": "Two distinct roster members independently satisfy the focal authorship condition, forming a jointly intended collection of (user, workspace) membership pairs; neither is more privileged than the other."
  },
  "negative_plan": {
    "type": "relationship_near_miss",
    "description": "A third roster member belongs to (is a member of) an audit channel where a launch-related message exists, but that message is authored by a different, non-roster user present in the same channel. The roster member's own message history in the audit channels contains no launch mention. This creates a plausible mis-binding: co-location of a roster member with a launch message in the same channel is not authorship. The near-miss membership must be excluded because it fails the focal authorship criterion while satisfying the roster/profile auxiliaries.",
    "filler": "A fourth roster member with a profile-shown workspace who is not a member of, and has no messages in, either audit channel, providing an uncomplicated non-match."
  },
  "environment_plan": "One workspace context (T_ACME) with a small roster of four named users, each carrying a single users.info-exposed workspace membership. Two audit channels hold realistic, fully paginated message histories: one channel contains a launch-related message from a roster author and a separate launch-related message from a non-roster co-member (the near-miss); a second channel contains a launch-related message from a second roster author. The fourth roster member has no presence in either audit channel. IDs are opaque native identifiers; no answer-revealing naming or ordering is used, and target/negative messages are interleaved with ordinary unrelated traffic (standup notes, scheduling chatter) in both channels.",
  "action_plan": "1. Read conversations.history for C_LAUNCH1 and C_LAUNCH2 (full pagination) to locate messages whose message_text contains 'launch', recording each message's author (user_id) and channel. [cards: WM-1]\n2. Read users.info for each of the four supplied roster candidates (U_ROSTER1..U_ROSTER4) to obtain each one's profile-shown workspace association. [cards: WM-1]\n3. Report the (user, workspace) membership entries only for roster candidates whose own user_id matches the author of a located launch-related message from step 1; exclude any roster candidate whose channel merely contains such a message authored by someone else, and exclude any roster candidate absent from the audit histories. [cards: WM-1]",
  "reason": null
}
```
